def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(n: int) -> bool:
        return all(ch == '9' for ch in str(n))

    s = str(num)
    length = len(s)

    # Special case: if all 9's, next palindrome is 10...01 with length+1 digits
    if is_all_nines(num):
        return num + 2  # e.g. 9->11, 99->101, 999->1001

    # Helper to create palindrome by mirroring left to right
    def make_palindrome(left: str, odd_len: bool) -> int:
        if odd_len:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd_len = (length % 2 != 0)
    mid = length // 2

    if odd_len:
        left = s[:mid+1]
    else:
        left = s[:mid]

    palindrome = make_palindrome(left, odd_len)
    if palindrome > num:
        return palindrome

    # increment the left half (including middle if odd)
    left_num = int(left) + 1
    left_str = str(left_num)

    # If incrementing left changes the length, e.g. 99 -> 100
    if len(left_str) > len(left):
        # This means palindrome length increases by 1 (e.g. 999 -> 1001)
        if odd_len:
            # For odd length, new palindrome length = length +1 and even
            return int(left_str + left_str[:-1][::-1])
        else:
            # For even length, new palindrome length = length +1 and odd
            return int(left_str + left_str[::-1])
    else:
        return make_palindrome(left_str, odd_len)

