    n = len(arr)

    # Check if already sorted without any shift
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all possible right shifts
    # A right shift by k means arr is rotated so that
    # the last k elements come to front.
    for k in range(1, n):
        shifted = arr[-k:] + arr[:-k]
        if all(shifted[i] <= shifted[i+1] for i in range(n-1)):
            return True

    return False

